Set-StrictMode -Version Latest;$ErrorActionPreference='Stop'
$workspace='D:\code\ntfs2refs';$base=Join-Path $workspace '.lab\hyperv\streaming-v2-20261027';$vmId=[guid]'2401593c-4b30-472e-9b6d-c9534cbaa599'
$run=[guid]::NewGuid().ToString('N');$root=Join-Path $base ('sparse-carrier-'+$run);$stage='C:\ntfs2refs\sparse-carrier-'+$run;$task='N2R-SparseCarrier-'+$run;$created=$false;$session=$null
function Need([bool]$Ok,[string]$Message){if(-not$Ok){throw $Message}}
function Tool([string]$Path,[string]$Pin,[string]$Name){$m=Get-Item -LiteralPath ([IO.Path]::GetFullPath($Path)) -Force;Need ($m-is[IO.FileInfo]-and$m.Length-gt0-and$m.Length-le64MB-and(Get-FileHash -LiteralPath $m.FullName).Hash.ToLowerInvariant()-ceq$Pin) 'Pinned ordinary executable required.';$a=$m;while($null-ne$a){Need (-not($a.Attributes-band[IO.FileAttributes]::ReparsePoint)) 'Reparse executable ancestry refused.';if($a-is[IO.DirectoryInfo]){$a=$a.Parent}else{$a=$a.Directory}};return @{path=$m.FullName;sha256=$Pin;bytes=$m.Length;name=$Name}}
function Save([string]$Name,$Value){$bytes=[Text.UTF8Encoding]::new($false).GetBytes(($Value|ConvertTo-Json -Depth 14));Need ($bytes.Length-le1MB) 'Host receipt exceeds one MiB.';$f=[IO.File]::Open((Join-Path $root $Name),'CreateNew','Write','Read');try{$f.Write($bytes,0,$bytes.Length);$f.Flush($true)}finally{$f.Dispose()}}
$ids=@($ExpectedCheckpointIds|ForEach-Object {$_.ToString('D')});Need ($ids.Count-gt0-and@($ids|Sort-Object -Unique).Count-eq$ids.Count-and$ExpectedParent.ToString('D')-in$ids) 'Exact current parent/checkpoint set required.'
function HostGuard{$vm=Get-VM -Id $vmId;$actual=@(Get-VMSnapshot -VM $vm|ForEach-Object {$_.Id.ToString('D')});Need ($vm.Name-ceq'ntfs2refs-streaming-v2-20261027'-and$vm.State.ToString()-ceq'Running'-and$vm.ParentSnapshotId-eq$ExpectedParent-and$vm.MemoryStartup-eq4GB-and$vm.MemoryAssigned-eq4GB-and-not$vm.DynamicMemoryEnabled-and(Get-VMProcessor -VM $vm).Count-eq4-and@(Get-VMNetworkAdapter -VM $vm).Count-eq0-and$actual.Count-eq$ids.Count-and@($ids|Where-Object {$_-notin$actual}).Count-eq0) 'Reviewed running VM, parent/checkpoints and resource limits required.'}
try{
 $tools=@((Tool $ManagedToolPath $ManagedToolSha256 'lab-managed-shadow.exe'),(Tool $ProbeToolPath $ProbeToolSha256 'lab-probe-sparse-carrier.exe'))
 Import-Module (Join-Path $PSScriptRoot 'Lab.psm1') -Force;$configuration=Get-LabConfiguration -WorkspaceRoot $workspace;$capacity=Get-LabCapacity -Configuration $configuration;Need ($capacity.MaximumActualBytes-eq329374052988-and$capacity.MinimumFreeBytes-eq17179869184) 'Fixed storage epoch differs.';Assert-LabCapacity -Capacity $capacity -AdditionalBytes 8GB;HostGuard
 New-Item -ItemType Directory -Path $root|Out-Null;$created=$true
