 $body=@'
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop'
$c=[Text.UTF8Encoding]::new($false).GetString([Convert]::FromBase64String('__CONFIG__'))|ConvertFrom-Json;$phase='preflight';$lastExit=$null
function Need([bool]$Ok,[string]$Message){if(-not$Ok){throw $Message}}
function Save([string]$Name,$Value){$bytes=[Text.UTF8Encoding]::new($false).GetBytes(($Value|ConvertTo-Json -Depth 14));Need ($bytes.Length-le1MB) 'Wrapper receipt exceeds one MiB.';$f=[IO.File]::Open((Join-Path $c.stage $Name),'CreateNew','Write','Read');try{$f.Write($bytes,0,$bytes.Length);$f.Flush($true)}finally{$f.Dispose()}}
function Json([string]$Path){$m=Get-Item -LiteralPath $Path -Force;Need ($Path.StartsWith($c.stage+'\',[StringComparison]::OrdinalIgnoreCase)-and$m-is[IO.FileInfo]-and$m.Length-gt0-and$m.Length-le1MB) 'Bounded ordinary staged JSON required.';$a=$m;while($null-ne$a){Need (-not($a.Attributes-band[IO.FileAttributes]::ReparsePoint)) 'Reparse staged JSON ancestry.';if($a-is[IO.DirectoryInfo]){$a=$a.Parent}else{$a=$a.Directory}};return ([IO.File]::ReadAllText($Path)|ConvertFrom-Json)}
function Idle{Need (@(Get-CimInstance Win32_Process|Where-Object {$_.Name-match'\A(?:ntfs2refs(?:-.+)?|lab-.+)\.exe\z'}).Count-eq0-and@(Get-ScheduledTask|Where-Object {$_.TaskName-like'N2R-*'-and$_.TaskName-cne$c.task-and$_.State.ToString()-notin@('Ready','Disabled')}).Count-eq0) 'Another project worker/task is active.'}
function Log([string]$Path){$m=Get-Item -LiteralPath $Path -Force;Need ($m-is[IO.FileInfo]-and$m.Length-le1MB-and-not($m.Attributes-band[IO.FileAttributes]::ReparsePoint)) 'Bounded ordinary native log required.';$reader=[IO.StreamReader]::new($Path);try{$buffer=[char[]]::new(16384);$count=$reader.ReadBlock($buffer,0,$buffer.Length);return @{path=$Path;bytes=$m.Length;sha256=(Get-FileHash -LiteralPath $Path).Hash.ToLowerInvariant();text=[string]::new($buffer,0,$count);truncated=($reader.Peek()-ne-1)}}finally{$reader.Dispose()}}
function Native([string]$Name,[string[]]$Arguments,[string]$Role){
 $tool=@($c.tools|Where-Object name -CEQ $Name);$path=Join-Path $c.stage $Name;Need ($tool.Count-eq1-and(Get-Item -LiteralPath $path).Length-eq$tool[0].bytes-and(Get-FileHash -LiteralPath $path).Hash.ToLowerInvariant()-ceq$tool[0].sha256) 'Staged native tool differs.'
 $argumentsText=($Arguments|ForEach-Object {Need ($_-cnotmatch'["\r\n\x00]') 'Unsafe argument.';$tail=$_.Length-$_.TrimEnd('\').Length;'"'+$_+('\'*$tail)+'"'})-join' ';$p=$null
 try{
