 Need ($lastExit-eq0) 'Managed shadow creation failed; preserve its report.'
 $managedPath=Join-Path $c.managed 'result.json';$managed=Json $managedPath;$b=$managed.binding;$disk=Get-Disk -Number $b.disk_number;$parts=@(Get-Partition -DiskNumber $b.disk_number|Where-Object PartitionNumber -EQ $b.identity.partition_number);$volume=$parts|Get-Volume
 Need ($managed.success-eq$true-and$managed.kind-ceq'new-owned-native-managed-shadow-smoke'-and$managed.source_binding_supplied-eq$false-and$managed.source_writes-eq0-and$managed.path-ceq(Join-Path $c.managed 'shadow.vhdx')-and[guid]$managed.virtual_disk_id-ne[guid]::Empty-and$b.disk_number-notin$beforeNumbers-and$b.disk_number-ne0-and$b.disk_number-ne1-and-not$disk.IsBoot-and-not$disk.IsSystem-and-not$disk.IsOffline-and-not$disk.IsReadOnly-and[guid]$disk.Guid-eq[guid]$b.identity.disk_guid-and$parts.Count-eq1-and[guid]$parts[0].Guid-eq[guid]$b.identity.partition_guid-and$parts[0].Offset-eq32MB-and$parts[0].Size-eq52GB-and$volume.FileSystem-ceq'ReFS'-and$volume.AllocationUnitSize-eq4096) 'Actual new owned shadow binding differs.'
 $request=@{schema_version=1;kind='sparse-carrier-probe-request';binding=$b;probe_id=$c.run_id};$bytes=[Text.UTF8Encoding]::new($false).GetBytes(($request|ConvertTo-Json -Depth 8));Need ($bytes.Length-le16384) 'Probe request too large.';$file=[IO.File]::Open($c.request,'CreateNew','Write','Read');try{$file.Write($bytes,0,$bytes.Length);$file.Flush($true)}finally{$file.Dispose()};$requestPin=(Get-FileHash -LiteralPath $c.request).Hash.ToLowerInvariant()
 Save 'managed-binding.json' @{binding=$b;owned_shadow_path=$managed.path;owned_virtual_disk_id=$managed.virtual_disk_id;managed_receipt_sha256=(Get-FileHash -LiteralPath $managedPath).Hash.ToLowerInvariant();request_sha256=$requestPin;source_binding_supplied=$false}
 Idle;$phase='sparse-carrier-probe';Native 'lab-probe-sparse-carrier.exe' @('--request',$c.request,'--request-sha256',$requestPin,'--output',$c.report,'--acknowledge-disposable-data-volume') 'probe'
