 Need ($success) 'Sparse carrier probe failed; native logs and any closed report remain preserved.'
}catch{Save 'wrapper-failed.json' @{success=$false;run_id=$c.run_id;phase=$phase;native_exit=$lastExit;error=$_.Exception.ToString();automatic_retry_cleanup=$false;utc=[DateTime]::UtcNow.ToString('o')};throw}
'@
