 Save 'dispatch.json' @{schema_version=1;kind='owned-sparse-carrier-dispatch';run_id=$run;vm_id=$vmId.ToString('D');parent_id=$ExpectedParent.ToString('D');checkpoint_ids=$ids;guest_stage=$stage;task_name=$task;wrapper_sha256=$wrapperPin;tools=$tools;report_path=$c.report;source_binding_supplied=$false;utc=[DateTime]::UtcNow.ToString('o')}
